/**
 * Delete DeviceFingerprint records older than the specified number of days.
 *
 * Unmatched fingerprints become useless after the attribution window closes.
 * Matched fingerprints are kept slightly longer for audit purposes but can
 * also be safely pruned — the InstallEvent / UserAttribution records retain
 * the attribution data independently.
 *
 * Default: 30 days for unmatched, 90 days for matched.
 */
export async function cleanupFingerprints(options?: {
  unmatchedDays?: number;
  matchedDays?: number;
}): Promise<{ deletedUnmatched: number; deletedMatched: number }> {
  const unmatchedDays = options?.unmatchedDays ?? 30;
  const matchedDays = options?.matchedDays ?? 90;

  const now = new Date();

  const unmatchedCutoff = new Date(
    now.getTime() - unmatchedDays * 24 * 60 * 60 * 1000
  );
